ALTER TABLE "PricingVersion" ADD CONSTRAINT "PricingVersion_effective_period_check" CHECK ("effectiveTo" IS NULL OR "effectiveFrom" IS NULL OR "effectiveTo" > "effectiveFrom");
ALTER TABLE "ServicePricingConfiguration" ADD CONSTRAINT "ServicePricingConfiguration_service_key_check" CHECK ("serviceKey" IN ('window-cleaning', 'pressure-washing', 'gutter-cleaning', 'moss-removal', 'vent-cleaning'));
ALTER TABLE "ServicePricingConfiguration" ADD CONSTRAINT "ServicePricingConfiguration_money_check" CHECK ("baseMinimumCents" >= 0 AND "baseMaximumCents" >= "baseMinimumCents" AND "minimumChargeCents" >= 0 AND "maximumEstimatorCents" >= "minimumChargeCents" AND "roundingIncrementCents" > 0);
ALTER TABLE "PricingRule" ADD CONSTRAINT "PricingRule_values_check" CHECK ("sortOrder" >= 0 AND ("adjustmentBasisPoints" IS NULL OR "adjustmentBasisPoints" >= -10000));
ALTER TABLE "EstimateResult" ADD CONSTRAINT "EstimateResult_service_key_check" CHECK ("serviceKey" IN ('window-cleaning', 'pressure-washing', 'gutter-cleaning', 'moss-removal', 'vent-cleaning'));
ALTER TABLE "EstimateResult" ADD CONSTRAINT "EstimateResult_area_key_check" CHECK ("serviceAreaKey" IN ('vancouver', 'richmond', 'burnaby', 'surrey', 'coquitlam', 'north-vancouver'));
ALTER TABLE "EstimateResult" ADD CONSTRAINT "EstimateResult_range_check" CHECK ("currency" = 'CAD' AND (("outcome" = 'RANGE' AND "minimumCents" IS NOT NULL AND "maximumCents" IS NOT NULL AND "minimumCents" >= 0 AND "maximumCents" >= "minimumCents") OR ("outcome" = 'MANUAL_REVIEW' AND "minimumCents" IS NULL AND "maximumCents" IS NULL)));
